`timescale 1ns/1ps
module tb_command_rx;localparam CPB=4;reg clk=0,reset_n=0,rx=1,ready=1;wire valid;wire[7:0]cmd;wire[15:0]seq;wire[31:0]payload;wire crc_error,frame_error;integer fails=0;always #5 clk=~clk;
sf_command_rx #(.UART_CLKS_PER_BIT(CPB))dut(.clk(clk),.reset_n(reset_n),.uart_rx(rx),.command_ready(ready),.command_valid(valid),.command_id(cmd),.command_sequence(seq),.command_payload(payload),.checksum_error(crc_error),.framing_error(frame_error));
function[7:0]crc8_next;input[7:0]current,inputv;integer i;reg[7:0]c;begin c=current^inputv;for(i=0;i<8;i=i+1)c=c[7]?((c<<1)^8'h07):(c<<1);crc8_next=c;end endfunction
task send_byte;input[7:0]v;integer i;begin rx=0;repeat(CPB)@(posedge clk);for(i=0;i<8;i=i+1)begin rx=v[i];repeat(CPB)@(posedge clk);end rx=1;repeat(CPB)@(posedge clk);end endtask
task send_frame;input[7:0]c;input[15:0]s;input[31:0]p;input corrupt;reg[7:0]crc;begin crc=0;crc=crc8_next(crc,8'h05);crc=crc8_next(crc,c);crc=crc8_next(crc,s[15:8]);crc=crc8_next(crc,s[7:0]);crc=crc8_next(crc,p[31:24]);crc=crc8_next(crc,p[23:16]);crc=crc8_next(crc,p[15:8]);crc=crc8_next(crc,p[7:0]);send_byte(8'hA6);send_byte(8'h6A);send_byte(8'h05);send_byte(c);send_byte(s[15:8]);send_byte(s[7:0]);send_byte(p[31:24]);send_byte(p[23:16]);send_byte(p[15:8]);send_byte(p[7:0]);send_byte(corrupt?(crc^8'h01):crc);end endtask
initial begin $dumpfile("build/tb_command_rx.vcd");$dumpvars(0,tb_command_rx);repeat(4)@(posedge clk);reset_n=1;ready=0;send_frame(8'h10,16'h1234,32'h40004000,0);repeat(3)@(posedge clk);if(!valid||cmd!==8'h10||seq!==16'h1234||payload!==32'h40004000)begin $display("FAIL good frame");fails=fails+1;end ready=1;repeat(2)@(posedge clk);ready=0;send_frame(8'h11,16'h1235,32'h3E004000,1);repeat(3)@(posedge clk);if(valid)begin $display("FAIL corrupt frame accepted");fails=fails+1;end if(fails==0)$display("TEST_RESULT: PASS command_rx");else $display("TEST_RESULT: FAIL command_rx fails=%0d",fails);$finish(fails!=0);end
endmodule
